        }
        if (x > 0) {
            int v = u - 1;
            long long cost = horizontal[u - 1] ? 0 : (long long)xs[x] - xs[x - 1];
            if (distances[u] + cost < distances[v]) {
                distances[v] = distances[u] + cost;
                decrease_key(v);
            }
        }
        if (y + 1 < ny) {
            int v = u + nx;
            long long cost = vertical[u] ? 0 : (long long)ys[y + 1] - ys[y];
            if (distances[u] + cost < distances[v]) {
                distances[v] = distances[u] + cost;
                decrease_key(v);
            }
        }
        if (y > 0) {
            int v = u - nx;
            long long cost = vertical[u - nx] ? 0 : (long long)ys[y] - ys[y - 1];
            if (distances[u] + cost < distances[v]) {
                distances[v] = distances[u] + cost;
                decrease_key(v);
            }
        }
    }

    printf("%lld\n", distances[target]);

    free(rectangles);
    free(xs);
    free(ys);
    free(horizontal);
    free(vertical);
    free(diff);
    free(distances);
    free(heap);
    free(position);
    return 0;
}
